"""Publish real browser evidence, without changing screenshot pixels."""
from pathlib import Path
import json,shutil,html
from PIL import Image
import numpy as np
p=Path(__file__).resolve().parents[1];out=p/'public/home-release-review';out.mkdir(parents=True,exist_ok=True)
shots={'before':'verification/home-release/before/cabin.png','day':'verification/home-release/after/cabin.png','manor':'verification/home-release/after/webkit-manor.png','garden':'verification/home-release/after/webkit-garden-overview.png','seat':'verification/home-release/after/webkit-sofa.png','bouquet':'verification/home-release/after/webkit-bouquet.png','surfaces':'verification/home-release/after/webkit-surfaces.png','night':'verification/home-release/after/webkit-cabin-night.png','small':'verification/home-release/after/webkit-small.png'}
for name,file in shots.items():
 im=Image.open(p/file).convert('RGB');im.save(out/(name+'.webp'),lossless=True,method=6,exact=True)
 assert np.array_equal(np.array(im),np.array(Image.open(out/(name+'.webp')).convert('RGB')))
reports={}
for name,file in {'chromium':'verification/home-release/chromium.json','webkit':'verification/home-release/webkit.json','artLayers':'verification/home-release/art-layers.json','update':'verification/home-release/update.json','chromiumOffline':'verification/play-results/chromium-offline.json','webkitOffline':'verification/play-results/webkit-offline.json'}.items():
 d=json.loads((p/file).read_text());assert not d['errors'];reports[name]=d
release=json.loads((p/'dist/offline-release.json').read_text());assert release['version']=='manor-home-20261107-1'
reports['finalReleaseManifest']={'version':release['version'],'files':release['files'],'bytes':sum(a['bytes']for a in release['assets'])+(p/'dist/offline-release.json').stat().st_size}
reports['notes']='Real browser mobile emulation, controlled test profiles; not a physical iPhone benchmark. Main operation journeys precede final material/state-art derivatives. Offline/update reports retain their actual build bytes; final release manifest is separate. Public-site final smoke runs after deployment.'
(out/'validation.json').write_text(json.dumps(reports,ensure_ascii=False,indent=2)+'\n');shutil.copy2(p/'src/assets/cottage/atlas.json',out/'assets.json')
style='''*{box-sizing:border-box}body{margin:0;background:#292730;color:#f3e5d5;font:15px/1.9 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:28px 18px 60px}h1{font:500 30px/1.5 serif}h2{font-size:21px;font-weight:500;margin-top:36px}p,figcaption{color:#cbbdbb}a{color:#efd0a6}img{width:100%;height:auto;display:block}figure{margin:0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.portrait{max-width:430px;margin:20px auto}figcaption{font-size:12px;padding:8px 0}details{background:#37313d;border-radius:10px;padding:16px;margin:16px 0}summary{min-height:44px;cursor:pointer}.pill{display:inline-block;padding:10px 18px;border:1px solid #b397a0;border-radius:10px;text-decoration:none}.stamp{font-size:10px;letter-spacing:2px;color:#c5a8bc}code{overflow-wrap:anywhere}@media(max-width:600px){.pair{grid-template-columns:1fr}h1{font-size:25px}}'''
def figure(name,caption):return '<figure><a href="'+name+'.webp"><img '+(''if name in ['before','day']else'loading="lazy" ')+'src="'+name+'.webp" alt="'+html.escape(caption)+'"></a><figcaption>'+html.escape(caption)+'</figcaption></figure>'
page='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>曦光庄园 · 新庄园与互动小屋实机</title><style>'+style+'</style></head><body><main><span class="stamp">XIGUANG MANOR · A HOME TO LIVE IN</span><h1>推开门，是属于小曦的小屋</h1><p>新门庭已接为正式默认庄园，小屋开始首轮高清重制。全部图片来自实际Phaser运行，不是素材图或概念图。</p><p><a class="pill" href="../?v=manor-home-20261107-1">进入正式游戏</a>　<a href="https://github.com/glenoliver1411-lang/english-valley/blob/main/xiguang-manor/source/MANOR_HOME_RELEASE.md">修改报告</a></p><h2>同一手机视口 · 小屋前后</h2><p>390×844/DPR2、相同清晨、初始家具布局及门口站位。新建筑底板与家具等比显示，镜头不拉伸。动态猫咪的位置可能不同。</p><div class="pair">'+figure('before','原小屋 · 完成入场淡入后的实机')+figure('day','本轮小屋 · 最终原画家具与底板实机')+'</div><h2>默认新庄园与实际花圃</h2><div class="pair">'+figure('manor','实际行走的新门庭，房门接回原玩法')+figure('garden','新增四个原存档花圃，可种植、浇水、等待及采收')+'</div><h2>家具可以使用</h2><div class="pair">'+figure('seat','沙发坐姿与前景遮挡；起身恢复原站位')+figure('bouquet','专项状态：原收藏的玫瑰、铃兰和紫花花束分别显示；场景里增加了玩家摆放的帘架')+'</div><h2>材质、夜晚与小屏幕</h2><div class="pair">'+figure('surfaces','操作示例：更换木地板与窄墙纸装饰条，家具及花束状态与主对比不同')+figure('night','操作示例：原游戏时钟切到夜晚，家具摆放与主对比不同')+'</div><div class="portrait">'+figure('small','375×667手机视口的真实操作画面')+'</div><details open><summary>已经接通的玩法</summary><p>花圃使用原plots；三棵树使用原魔法糖索引，奖励只领一次。房门通花铺、小屋、工坊，花径通花园、花海、湖畔，石径通遗迹。换装、收藏和技能可从庄园地图打开。</p><p>小屋的茶桌、钢琴、椅子、灯、帘、猫窝、花架、衣柜、书架、床、礼物和信件可使用。原摆放、翻转、收起、换色、天气与单存档保留。</p></details><details><summary>真实测试、资源与当前边界</summary><p>100个Node测试通过；Chromium/WebKit实际操作与严格断网回归通过。家具编辑中不会因发现更新自动刷新。<a href="validation.json">原始验证记录</a>保留不同阶段的真实缓存字节与纹理数量。</p><p>最终发行清单94项、23,716,802字节。所有新增运行图本地打包，无损WebP逐像素对应PNG；<a href="assets.json">素材尺寸、来源与哈希</a>保留。未新增第三方下载或商业游戏截图。</p><p>本轮不是全地图完成。原32×40角色仍需后续细化，夜景尚非专门重绘的整套原画，墙纸是装饰条，部分家具足迹偏保守；森林等区域继续按全图规划推进。没有声称实体iPhone稳定60帧。</p></details></main></body></html>'
(out/'index.html').write_text(page)
print('Prepared real-game review; every displayed screenshot pixel retained.')
